var gw_time_ms = 0.0

func gw_config():
	return JSON.parse(JavaScript.eval("JSON.stringify(window.__fairSquares.config())", true)).result

func gw_event(event, payload = {}):
	if OS.has_feature("JavaScript"):
		JavaScript.eval("window.__fairSquares.event(" + JSON.print(event) + "," + JSON.print(payload) + ")", true)

func gw_unit_info(unit):
	var max_health = unit.data.max_hp if "data" in unit else unit.max_hp
	return {"id":str(unit.get_instance_id()), "name":unit.name, "hp":unit.hp, "max_hp":max_health, "x":unit.global_position.x, "y":unit.global_position.y, "cutscene":unit.get("in_cutscene") == true, "boss":not ("data" in unit)}

func gw_context(level):
	return {"world":level.world,"kind":level.type,"arena":level.level_ind}

func gw_round_ready(level):
	var info = gw_context(level)
	info["enemies"] = []
	for unit in level.get_node("Units").get_children():
		if "hp" in unit and not unit.is_queued_for_deletion():
			info.enemies.append(gw_unit_info(unit))
	gw_event("round_ready", info)

func gw_player_died(_pos):
	gw_event("player_died")

gw_time_ms += delta * 1000.0
var level = get_node_or_null("/root/Main/Level")
if not level:

var info = gw_context(level)
info["game_time_ms"] = gw_time_ms
info["rounds_left"] = level.rounds_left
info["fighting"] = level.fighting
info["resetting"] = level.reset
info["layout"] = level.fname
info["player"] = null
info["gun"] = null
if player and is_instance_valid(player):
	info.player = {"hp":player.hp,"max_hp":player.data.max_hp,"x":player.global_position.x,"y":player.global_position.y,"cutscene":player.in_cutscene}
if gun and is_instance_valid(gun):
	info.gun = {"ammo":gun.ammo,"max_ammo":gun.max_ammo,"reloading":gun.get_node("ReloadAnim").is_playing(),"enabled":gun.enabled}
info["enemies"] = []
for unit in level.get_node("Units").get_children():
	if "hp" in unit and not unit.is_queued_for_deletion():
		info.enemies.append(gw_unit_info(unit))
info["portals"] = []
for portal in level.get_node("Spawns").get_children():
	if "upgrade" in portal and not portal.is_queued_for_deletion():
		info.portals.append({"upgrade":portal.upgrade,"custom":portal.custom,"ready":portal.monitoring,"x":portal.global_position.x,"y":portal.global_position.y})
